<?php cms_view('public/hero',compact('page'));?><main class="careers-page"><section class="section-padding careers-intro-section"><div class="container"><div class="careers-intro-grid"><div><span class="section-kicker"><?=text('work_with_us')?></span><h2 class="section-title"><?=text('career_intro_title')?></h2></div><div class="careers-rich"><?php if($page['body']):?><?=rich($page['body'])?><?php else:?><p><?=text('career_intro')?></p><?php endif?></div></div></div></section><section class="section-padding careers-openings-section"><div class="container"><div class="catalog-toolbar careers-toolbar"><div><span class="section-kicker"><?=text('open_positions')?></span><h2 class="section-title mb-1"><?=text('job_openings')?></h2></div></div><div class="careers-opening-list"><?php foreach($jobs as $job):?><article class="careers-opening-card reveal"><div class="careers-opening-head"><div><h3><?=e($job['title'])?></h3><div class="careers-meta"><?php foreach(['department'=>'briefcase','location'=>'location-dot','employment_type'=>'clock','experience'=>'user-check'] as $key=>$icon):if(!$job[$key])continue;?><span><i class="fa-solid fa-<?=$icon?>"></i><?=e($job[$key])?></span><?php endforeach?></div></div><?php $apply=$job['apply_url']?:($job['apply_email']?'mailto:'.$job['apply_email'].'?subject='.rawurlencode('Application for '.$job['title']):'');if($apply):?><a class="careers-apply-btn" href="<?=e(cms_url($apply))?>"><?=text('apply_now')?></a><?php endif?></div><div class="careers-summary rich-text"><?=rich($job['description'])?></div><div class="careers-opening-body"><?php if($job['responsibilities']):?><div><h4><?=text('responsibilities')?></h4><?=rich($job['responsibilities'])?></div><?php endif?><?php if($job['qualifications']):?><div><h4><?=text('requirements')?></h4><?=rich($job['qualifications'])?></div><?php endif?></div></article><?php endforeach?><?php if(!$jobs):?><div class="careers-empty"><i class="fa-solid fa-inbox"></i><h3><?=text('no_openings')?></h3><p><